package com.cattlefarm.admin.feeding;
import cn.dev33.satoken.stp.StpUtil;import com.baomidou.mybatisplus.core.toolkit.IdWorker;import com.cattlefarm.admin.auth.service.AuthService;import com.cattlefarm.admin.common.DataConflictException;import com.cattlefarm.admin.scope.DataScopeService;import com.cattlefarm.admin.task.TaskService;import org.springframework.dao.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;import java.util.stream.Collectors;
@Service
public class FeedingService{
 private final JdbcTemplate jdbc;private final AuthService auth;private final TaskService tasks;private final DataScopeService scope;public FeedingService(JdbcTemplate jdbc,AuthService auth,TaskService tasks,DataScopeService scope){this.jdbc=jdbc;this.auth=auth;this.tasks=tasks;this.scope=scope;}
 public List<FeedingDtos.Ingredient>ingredients(){long farm=auth.currentFarmId();return jdbc.query("SELECT * FROM feed_ingredient WHERE farm_id=? ORDER BY status,ingredient_name",(r,n)->mapIngredient(r),farm);}
 @Transactional public FeedingDtos.Ingredient createIngredient(FeedingDtos.CreateIngredient r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/feeding/ingredients";Long old=replay(farm,user,key,path);if(old!=null)return ingredient(old);long id=IdWorker.getId();idem(farm,user,key,path,id);try{jdbc.update("INSERT INTO feed_ingredient(ingredient_id,farm_id,ingredient_name,ingredient_type,dry_matter_pct,tdn_pct,crude_protein_pct,starch_pct,energy_value,gain_energy_value,ndf_pct,rdp_pct,unit_price,remark,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,farm,r.ingredientName().trim(),r.ingredientType(),r.dryMatterPct(),r.tdnPct(),r.crudeProteinPct(),r.starchPct(),r.energyValue(),r.gainEnergyValue(),r.ndfPct(),r.rdpPct(),r.unitPrice(),r.remark(),user,user);}catch(DuplicateKeyException e){throw new DataConflictException("同一牛场内原料名称不能重复");}audit(farm,user,"INGREDIENT_CREATED","FEED_INGREDIENT",id,r.ingredientName());return ingredient(id);}
 public List<FeedingDtos.Formula>formulas(){long farm=auth.currentFarmId();return jdbc.query("SELECT formula_id FROM ration_formula WHERE farm_id=? ORDER BY created_at DESC",(r,n)->r.getLong(1),farm).stream().map(this::formulaDetail).toList();}
 @Transactional public FeedingDtos.Formula createFormula(FeedingDtos.CreateFormula r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/feeding/ration-formulas";Long old=replay(farm,user,key,path);if(old!=null)return formula(old);Set<String>unique=new HashSet<>();BigDecimal sum=BigDecimal.ZERO;for(var x:r.items()){if(!unique.add(x.ingredientId()))throw new DataConflictException("配方中不能重复选择同一种原料");sum=sum.add(x.dailyAmountKg());ingredientForFarm(parse(x.ingredientId()),farm);}if(sum.subtract(r.dailyIntakeKg()).abs().compareTo(new BigDecimal("0.01"))>0)throw new DataConflictException("各原料日用量合计必须等于日采食量");Integer v=jdbc.queryForObject("SELECT COALESCE(MAX(version_no),0)+1 FROM ration_formula WHERE farm_id=? AND formula_name=?",Integer.class,farm,r.formulaName().trim());long id=IdWorker.getId();idem(farm,user,key,path,id);jdbc.update("INSERT INTO ration_formula(formula_id,farm_id,formula_name,version_no,target_type,target_object_id,daily_intake_kg,source_file,remark,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,farm,r.formulaName().trim(),v,r.targetType(),optional(r.targetObjectId()),r.dailyIntakeKg(),"葵花日粮计算（九版）.xlsx（百分比口径已统一，人工录入）",r.remark(),user,user);int sort=0;for(var x:r.items())jdbc.update("INSERT INTO ration_formula_item(item_id,farm_id,formula_id,ingredient_id,ratio_pct,daily_amount_kg,sort_no) VALUES(?,?,?,?,?,?,?)",IdWorker.getId(),farm,id,parse(x.ingredientId()),x.ratioPct(),x.dailyAmountKg(),sort++);audit(farm,user,"FORMULA_CREATED","RATION_FORMULA",id,r.formulaName());return formula(id);}
 @Transactional public FeedingDtos.Formula activate(long id,FeedingDtos.Action r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/feeding/ration-formulas/"+id+"/activate";Long old=replay(farm,user,key,path);if(old!=null)return formula(old);FeedingDtos.Formula f=formula(id);if("ACTIVE".equals(f.status()))return f;idem(farm,user,key,path,id);jdbc.update("UPDATE ration_formula SET status='ARCHIVED',updated_by=?,version=version+1 WHERE farm_id=? AND formula_name=? AND status='ACTIVE'",user,farm,f.formulaName());int n=jdbc.update("UPDATE ration_formula SET status='ACTIVE',updated_by=?,version=version+1 WHERE formula_id=? AND farm_id=? AND version=? AND status='DRAFT'",user,id,farm,r.version());if(n==0)throw new DataConflictException("配方状态已变化，请刷新后重试");audit(farm,user,"FORMULA_ACTIVATED","RATION_FORMULA",id,r.reason());return formula(id);}
 public List<FeedingDtos.Order>orders(){long farm=auth.currentFarmId();return jdbc.query("SELECT mixing_order_id FROM mixing_order WHERE farm_id=? ORDER BY feed_date DESC,created_at DESC",(r,n)->r.getLong(1),farm).stream().filter(id->scope.unrestricted()||scope.canAccessMixingOrder(id)).map(this::order).toList();}
 @Transactional public FeedingDtos.Order createOrder(FeedingDtos.CreateOrder r,String key){return createOrder(r,key,"/api/v1/feeding/mixing-orders");}
 @Transactional public FeedingDtos.Order createOrder(FeedingDtos.CreateOrder r,String key,String path){long farm=auth.currentFarmId(),user=user();Long old=replay(farm,user,key,path);if(old!=null)return order(old);long formulaId=parse(r.formulaId());FeedingDtos.Formula f=formula(formulaId);if(!"ACTIVE".equals(f.status()))throw new DataConflictException("只能使用已启用的配方创建配料单");Long herd=optional(r.targetHerdId()),assignee=optional(r.assigneeId());if(herd!=null&&count("herd","herd_id",farm,herd)==0)throw new DataConflictException("牛群不存在");if(assignee==null)assignee=user;if(countMember(farm,assignee)==0)throw new DataConflictException("负责人不是当前牛场的启用成员");long id=IdWorker.getId();idem(farm,user,key,path,id);jdbc.update("INSERT INTO mixing_order(mixing_order_id,farm_id,formula_id,target_herd_id,cattle_count,feed_date,assignee_id,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?)",id,farm,formulaId,herd,r.cattleCount(),r.feedDate(),assignee,user,user);for(var x:f.items())jdbc.update("INSERT INTO mixing_order_item(item_id,farm_id,mixing_order_id,ingredient_id,planned_amount_kg) VALUES(?,?,?,?,?)",IdWorker.getId(),farm,id,parse(x.ingredientId()),x.dailyAmountKg().multiply(BigDecimal.valueOf(r.cattleCount())));audit(farm,user,"MIXING_ORDER_CREATED","MIXING_ORDER",id,"创建配料单");return order(id);}
 @Transactional public FeedingDtos.Order confirm(long id,FeedingDtos.Action r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/feeding/mixing-orders/"+id+"/confirm";Long old=replay(farm,user,key,path);if(old!=null)return order(old);FeedingDtos.Order o=order(id);if("CONFIRMED".equals(o.status()))return o;if(!"PENDING_CONFIRM".equals(o.status()))throw new DataConflictException("当前状态不能确认");idem(farm,user,key,path,id);int n=jdbc.update("UPDATE mixing_order SET status='CONFIRMED',confirm_reason=?,updated_by=?,version=version+1 WHERE mixing_order_id=? AND farm_id=? AND version=?",r.reason(),user,id,farm,r.version());if(n==0)throw new DataConflictException("配料单已被其他人修改，请刷新后重试");tasks.createAutomatic(farm,id,"MIXING_ORDER","MIXING_EXECUTION","执行配料："+o.formulaName(),null,optionalHerd(id,farm),null,o.feedDate(),o.feedDate(),user,"IMPORTANT");audit(farm,user,"MIXING_ORDER_CONFIRMED","MIXING_ORDER",id,r.reason());return order(id);}
 @Transactional public FeedingDtos.Order execute(long id,FeedingDtos.Execute r,String key){long farm=auth.currentFarmId(),user=user();String path="/api/v1/feeding/mixing-orders/"+id+"/execute";Long old=replay(farm,user,key,path);if(old!=null)return order(old);FeedingDtos.Order o=order(id);if("EXECUTED".equals(o.status()))return o;if(!"CONFIRMED".equals(o.status()))throw new DataConflictException("配料单确认后才能执行");Map<String,BigDecimal>actual=r.items().stream().collect(Collectors.toMap(FeedingDtos.ActualItem::ingredientId,FeedingDtos.ActualItem::actualAmountKg,(a,b)->{throw new DataConflictException("实投原料不能重复");}));if(!actual.keySet().equals(o.items().stream().map(FeedingDtos.OrderLine::ingredientId).collect(Collectors.toSet())))throw new DataConflictException("实投原料必须与配料单明细一致");idem(farm,user,key,path,id);int n=jdbc.update("UPDATE mixing_order SET status='EXECUTED',updated_by=?,version=version+1 WHERE mixing_order_id=? AND farm_id=? AND version=?",user,id,farm,r.version());if(n==0)throw new DataConflictException("配料单已被其他人修改，请刷新后重试");String summary=actual.entrySet().stream().map(e->e.getKey()+":"+e.getValue().stripTrailingZeros().toPlainString()+"kg").collect(Collectors.joining(","));jdbc.update("INSERT INTO mixing_execution(execution_id,farm_id,mixing_order_id,execution_time,executor_id,actual_summary,deviation_note,created_at) VALUES(?,?,?,?,?,?,?,NOW())",IdWorker.getId(),farm,id,r.executionTime(),user,summary,r.deviationNote());tasks.finishSource(farm,"MIXING_ORDER",id,"MIXING_EXECUTION","配料执行完成",user,"DONE");audit(farm,user,"MIXING_ORDER_EXECUTED","MIXING_ORDER",id,r.deviationNote());return order(id);}
 public FeedingDtos.Ingredient ingredientDetail(long id){return ingredient(id);}public FeedingDtos.Formula formulaDetail(long id){FeedingDtos.Formula f=formula(id);Integer v=jdbc.queryForObject("SELECT version FROM ration_formula WHERE formula_id=? AND farm_id=?",Integer.class,id,auth.currentFarmId());return new FeedingDtos.Formula(f.formulaId(),f.formulaName(),f.versionNo(),f.targetType(),f.targetObjectId(),f.dailyIntakeKg(),f.sourceFile(),f.status(),f.dryMatterKg(),f.crudeProteinPct(),f.ndfPct(),f.dailyCost(),f.items(),v==null?0:v);}public FeedingDtos.Order orderDetail(long id){return order(id);}private FeedingDtos.Ingredient ingredient(long id){long farm=auth.currentFarmId();return ingredientForFarm(id,farm);}private FeedingDtos.Ingredient ingredientForFarm(long id,long farm){try{return jdbc.queryForObject("SELECT * FROM feed_ingredient WHERE ingredient_id=? AND farm_id=?",(r,n)->mapIngredient(r),id,farm);}catch(EmptyResultDataAccessException e){throw new DataConflictException("原料不存在");}}
 private FeedingDtos.Formula formula(long id){long farm=auth.currentFarmId();try{return jdbc.queryForObject("SELECT * FROM ration_formula WHERE formula_id=? AND farm_id=?",(r,n)->{List<FeedingDtos.FormulaLine>lines=jdbc.query("SELECT i.ingredient_id,i.ingredient_name,x.ratio_pct,x.daily_amount_kg,i.unit_price FROM ration_formula_item x JOIN feed_ingredient i ON i.ingredient_id=x.ingredient_id AND i.farm_id=x.farm_id WHERE x.formula_id=? AND x.farm_id=? ORDER BY x.sort_no",(q,k)->new FeedingDtos.FormulaLine(s(q.getLong(1)),q.getString(2),q.getBigDecimal(3),q.getBigDecimal(4),q.getBigDecimal(5)),id,farm);BigDecimal intake=r.getBigDecimal("daily_intake_kg"),dm=z(),cp=z(),ndf=z(),cost=z();for(var x:lines){var i=ingredientForFarm(parse(x.ingredientId()),farm);dm=dm.add(x.dailyAmountKg().multiply(orZero(i.dryMatterPct())).divide(bd(100)));cp=cp.add(x.dailyAmountKg().multiply(orZero(i.crudeProteinPct())));ndf=ndf.add(x.dailyAmountKg().multiply(orZero(i.ndfPct())));cost=cost.add(x.dailyAmountKg().multiply(orZero(i.unitPrice())));}cp=cp.divide(intake,2,RoundingMode.HALF_UP);ndf=ndf.divide(intake,2,RoundingMode.HALF_UP);return new FeedingDtos.Formula(s(id),r.getString("formula_name"),r.getInt("version_no"),r.getString("target_type"),obj(r.getObject("target_object_id")),intake,r.getString("source_file"),r.getString("status"),dm.setScale(3,RoundingMode.HALF_UP),cp,ndf,cost.setScale(2,RoundingMode.HALF_UP),lines);},id,farm);}catch(EmptyResultDataAccessException e){throw new DataConflictException("配方不存在");}}
 private FeedingDtos.Order order(long id){long farm=auth.currentFarmId();if(!scope.unrestricted())scope.assertMixingOrder(id);try{return jdbc.queryForObject("SELECT o.*,f.formula_name,h.herd_name FROM mixing_order o JOIN ration_formula f ON f.formula_id=o.formula_id AND f.farm_id=o.farm_id LEFT JOIN herd h ON h.herd_id=o.target_herd_id AND h.farm_id=o.farm_id WHERE o.mixing_order_id=? AND o.farm_id=?",(r,n)->{List<FeedingDtos.OrderLine>lines=jdbc.query("SELECT i.ingredient_id,i.ingredient_name,x.planned_amount_kg,x.adjusted_amount_kg,i.unit_price FROM mixing_order_item x JOIN feed_ingredient i ON i.ingredient_id=x.ingredient_id AND i.farm_id=x.farm_id WHERE x.mixing_order_id=? AND x.farm_id=?",(q,k)->new FeedingDtos.OrderLine(s(q.getLong(1)),q.getString(2),q.getBigDecimal(3),q.getBigDecimal(4),q.getBigDecimal(5)),id,farm);BigDecimal total=lines.stream().map(x->x.adjustedAmountKg()==null?x.plannedAmountKg():x.adjustedAmountKg()).reduce(z(),BigDecimal::add);BigDecimal cost=lines.stream().map(x->(x.adjustedAmountKg()==null?x.plannedAmountKg():x.adjustedAmountKg()).multiply(orZero(x.unitPrice()))).reduce(z(),BigDecimal::add);return new FeedingDtos.Order(s(id),s(r.getLong("formula_id")),r.getString("formula_name"),r.getString("herd_name"),r.getInt("cattle_count"),r.getDate("feed_date").toLocalDate(),r.getString("status"),total.setScale(3,RoundingMode.HALF_UP),cost.setScale(2,RoundingMode.HALF_UP),r.getInt("version"),lines);},id,farm);}catch(EmptyResultDataAccessException e){throw new DataConflictException("配料单不存在");}}
 private static FeedingDtos.Ingredient mapIngredient(java.sql.ResultSet r)throws java.sql.SQLException{return new FeedingDtos.Ingredient(s(r.getLong("ingredient_id")),r.getString("ingredient_name"),r.getString("ingredient_type"),r.getBigDecimal("dry_matter_pct"),r.getBigDecimal("tdn_pct"),r.getBigDecimal("crude_protein_pct"),r.getBigDecimal("starch_pct"),r.getBigDecimal("energy_value"),r.getBigDecimal("gain_energy_value"),r.getBigDecimal("ndf_pct"),r.getBigDecimal("rdp_pct"),r.getBigDecimal("unit_price"),r.getString("status"),r.getString("remark"),r.getInt("version"));}
 private void audit(long f,long u,String a,String t,long id,String reason){jdbc.update("INSERT INTO operation_log(operation_log_id,farm_id,user_id,module_code,action_type,business_type,business_id,reason) VALUES(?,?,?,'FEEDING',?,?,?,?)",IdWorker.getId(),f,u,a,t,id,reason);}private void idem(long f,long u,String k,String p,long id){jdbc.update("INSERT INTO idempotency_record(farm_id,user_id,idempotency_key,request_path,business_id,expires_at) VALUES(?,?,?,?,?,?)",f,u,k,p,id,LocalDateTime.now().plusDays(1));}private Long replay(long f,long u,String k,String p){try{return jdbc.queryForObject("SELECT business_id FROM idempotency_record WHERE farm_id=? AND user_id=? AND idempotency_key=? AND request_path=? AND expires_at>NOW()",Long.class,f,u,k,p);}catch(EmptyResultDataAccessException e){return null;}}private long user(){return StpUtil.getLoginIdAsLong();}private long parse(String x){try{return Long.parseLong(x);}catch(Exception e){throw new DataConflictException("编号格式错误");}}private Long optional(String x){return x==null||x.isBlank()?null:parse(x);}private Long optionalHerd(long id,long farm){return jdbc.queryForObject("SELECT target_herd_id FROM mixing_order WHERE mixing_order_id=? AND farm_id=?",Long.class,id,farm);}private int countMember(long farm,long user){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM sys_user u JOIN farm_user fu ON fu.user_id=u.user_id AND fu.farm_id=u.farm_id WHERE u.farm_id=? AND u.user_id=? AND u.status='ENABLED' AND fu.status='ENABLED'",Integer.class,farm,user);return n==null?0:n;}private int count(String t,String pk,long f,long id){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM "+t+" WHERE farm_id=? AND "+pk+"=?",Integer.class,f,id);return n==null?0:n;}private static String s(long x){return Long.toString(x);}private static String obj(Object x){return x==null?null:x.toString();}private static BigDecimal z(){return BigDecimal.ZERO;}private static BigDecimal bd(long x){return BigDecimal.valueOf(x);}private static BigDecimal orZero(BigDecimal x){return x==null?z():x;}
}
